// Executes original, pinned TypeScript bodies; generated bytes are test data only.
import {readFileSync, writeFileSync, mkdirSync} from "node:fs";
import path from "node:path";
import {pathToFileURL} from "node:url";
import {createHash} from "node:crypto";
const [reference, output, repository] = process.argv.slice(2);
const source = path.join(reference, "TypeScript");
const {build} = await import(pathToFileURL(path.join(repository, "Apps", "LiteTests",
    "LitePlayground", "JavaScript", "node_modules", "esbuild", "lib", "main.js")));
const entries = ["mesh\\create-torus.ts", "mesh\\create-ground.ts", "math\\compose-mat4-into-buffer.ts"];
const provenance = JSON.parse(readFileSync(path.join(reference, "provenance.json"), "utf8"));
const sha = bytes => createHash("sha256").update(bytes).digest("hex");
mkdirSync(output, {recursive: true});
const modules = [];
for (const name of entries) {
    const bytes = readFileSync(path.join(source, name));
    if (sha(Buffer.from(bytes.toString().replaceAll("\r\n", "\n"))) !==
        provenance.files[name.replaceAll("\\", "/")]) throw Error("Source pin/hash mismatch: " + name);
    const bundled = await build({entryPoints: [path.join(source, name)], bundle: true,
        format: "esm", platform: "node", write: false});
    modules.push(await import("data:text/javascript;base64," +
        Buffer.from(bundled.outputFiles[0].contents).toString("base64")));
}
const cases = [
    ["torus-default", {}],
    ["torus-one", {tessellation: 1}],
    ["torus-zero", {diameter: 0, thickness: 0, tessellation: 2}],
    ["torus-negative", {diameter: -2, thickness: .7, tessellation: 7}],
    ["torus-scene162", {diameter: 2, thickness: .45, tessellation: 64}],
];
const manifest = {pin: provenance.sourcePin, sources: entries, cases: []};
function save(name, value, options) {
    const streams = {};
    for (const key of ["positions", "normals", "uvs", "indices"]) {
        const array = value[key];
        const bytes = Buffer.from(array.buffer, array.byteOffset, array.byteLength);
        writeFileSync(path.join(output, name + "-" + key + ".bin"), bytes);
        streams[key] = {elements: array.length, sha256: sha(bytes)};
    }
    manifest.cases.push({name, options, streams});
}
for (const [name, options] of cases) save(name, modules[0].createTorusData(options), options);
const pixels = new Uint8ClampedArray([
    255,0,0,0, 0,255,0,255, 0,0,255,0,
    255,255,255,255, 0,0,0,255, 50,100,150,0,
]);
globalThis.Image = class {
    width = 3; height = 2;
    set src(value) { queueMicrotask(() => this.onload()); }
};
globalThis.document = {createElement() { return {getContext() { return {
    drawImage() {}, getImageData() { return {data: pixels}; },
}; }}; }};
const options = {width: 3, height: 5, subdivisions: 3, minHeight: -2, maxHeight: 5, uvScale: [1.3,-2.2]};
save("heightmap", await modules[1].createGroundFromHeightMap("oracle", options), options);
const values = [5000000.123456, -2.7, -5000000.654321, .1, -.2, .3, .9, -2, 0, 3.7];
for (const precise of [false, true]) {
    const array = precise ? new Float64Array(16) : new Float32Array(16);
    modules[2].composeMat4IntoBuffer(array, 0, ...values);
    writeFileSync(path.join(output, `compose-${precise ? "f64" : "f32"}.bin`),
        Buffer.from(array.buffer));
}
writeFileSync(path.join(output, "manifest.json"), JSON.stringify(manifest, null, 2) + "\n");
